import type NextNodeServer from 'next/dist/server/next-server.js';

type Segment =
  | { kind: 'static'; value: string }
  | { kind: 'dynamic' | 'catch-all' | 'optional-catch-all'; name: string };

interface Route {
  segments: Segment[];
  filename: string;
}

/** Order segments are tried in at the same position, the same order Next.js uses. */
const rank = { static: 0, dynamic: 1, 'catch-all': 2, 'optional-catch-all': 3 } as const;

/**
 * Split a route path generated by Next.js, such as `/rooms/[room]`, into segments.
 *
 * @param routePath Route path
 * @returns Segments
 */
function parseRoutePath(routePath: string): Segment[] {
  return routePath
    .split('/')
    .filter(Boolean)
    .map((part) => {
      const optional = /^\[\[\.\.\.(.+)\]\]$/.exec(part);
      if (optional) return { kind: 'optional-catch-all', name: optional[1]! };
      const catchAll = /^\[\.\.\.(.+)\]$/.exec(part);
      if (catchAll) return { kind: 'catch-all', name: catchAll[1]! };
      const dynamic = /^\[(.+)\]$/.exec(part);
      if (dynamic) return { kind: 'dynamic', name: dynamic[1]! };
      return { kind: 'static', value: part };
    });
}

/** Sort routes so the most specific one comes first, segment by segment. */
function compareRoutes(a: Route, b: Route) {
  for (let i = 0; i < Math.max(a.segments.length, b.segments.length); i++) {
    const x = a.segments[i];
    const y = b.segments[i];
    // A route that has ended is more specific than one that goes on to an optional catch-all
    const difference = (x ? rank[x.kind] : -1) - (y ? rank[y.kind] : -1);
    if (difference !== 0) return difference;
  }
  return 0;
}

/**
 * Decode a URI component, leaving it as is if it is malformed.
 *
 * @param value Encoded value
 * @returns Decoded value
 */
function decode(value: string) {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

/**
 * Match the parts of a request pathname against a route's segments.
 *
 * @param segments Route segments
 * @param parts Pathname parts, still encoded
 * @returns Parameters if the route matches
 */
function matchSegments(segments: Segment[], parts: string[]) {
  const params: Record<string, string | string[]> = {};
  for (const [i, segment] of segments.entries()) {
    if (segment.kind === 'catch-all' || segment.kind === 'optional-catch-all') {
      const rest = parts.slice(i);
      if (rest.length > 0) params[segment.name] = rest.map(decode);
      else if (segment.kind === 'catch-all') return null;
      return params;
    }

    const part = parts[i];
    if (part === undefined) return null;
    if (segment.kind === 'static') {
      if (part !== segment.value && decode(part) !== segment.value) return null;
    } else params[segment.name] = decode(part);
  }
  return parts.length === segments.length ? params : null;
}

/** Sorted routes of production servers, whose routes never change. */
const routeCache = new WeakMap<NextNodeServer, Route[]>();

function getRoutes(nextServer: NextNodeServer) {
  const cached = routeCache.get(nextServer);
  if (cached) return cached;

  const appPathRoutes: Record<string, string[] | undefined> = {
    // @ts-expect-error - appPathRoutes is protected
    ...nextServer.appPathRoutes,
    // @ts-expect-error - getAppPathRoutes is protected
    ...nextServer.getAppPathRoutes(),
  };
  const routes = Object.entries(appPathRoutes)
    .filter(([routePath, files]) => routePath && files?.[0])
    .map(([routePath, files]) => ({ segments: parseRoutePath(routePath), filename: files![0]! }))
    .sort(compareRoutes);

  // Routes appear as they are compiled in development
  // @ts-expect-error - serverOptions is protected
  if (!nextServer.serverOptions?.dev) routeCache.set(nextServer, routes);
  return routes;
}

/**
 * Find the matching route for a given request pathname.
 *
 * @param nextServer Next.js Node server instance
 * @param requestPathname Request pathname
 * @returns Object containing the filename and parameters
 */
export function findMatchingRoute(nextServer: NextNodeServer, requestPathname: string) {
  // @ts-expect-error - serverOptions is protected
  const basePath: string = nextServer.serverOptions?.conf.basePath || '';

  let pathname = requestPathname;
  if (basePath) {
    if (pathname !== basePath && !pathname.startsWith(`${basePath}/`)) return undefined;
    pathname = pathname.slice(basePath.length);
  }
  const parts = pathname.split('/').filter(Boolean);

  for (const route of getRoutes(nextServer)) {
    const params = matchSegments(route.segments, parts);
    if (params) return { filename: route.filename, params };
  }
  return undefined;
}
